if (clashName) {
  // DEFAULT: skip (below). OPT-IN (MIGRATE_RENAME_CLONE_CONTAINERS=1):
  // bring the clone up under namespaced container names + its own compose
  // project instead. Renaming container_name is safe for a SELF-CONTAINED
  // clone because compose still provides intra-project DNS by SERVICE name;
  // it can break only if another project references the clone's containers
  // by their old absolute name (rare) — which is why this is opt-in. Any
  // failure in the rename path falls back to the unchanged skip below; it
  // must never throw out of the loop.
  let renamed = false;
  if (RENAME_CLONE_CONTAINERS) {
    try {
      renamed = await (async (): Promise<boolean> => {
        // 1. dir basename → compose project name (lowercase, [^a-z0-9] stripped).
        const proj = (dir.replace(/\/+$/, "").split("/").pop() || "").toLowerCase().replace(/[^a-z0-9]/g, "");
        if (!proj) return false;
        // 2. Resolve services + their pinned container_names on the TARGET.
        const cfgRaw = clean((await sh(conn, `sh -c 'cd ${dir} && ${composeCmd} ${ce.fileArg}${ce.args}config --format json 2>/dev/null'`)).stdout, 2_000_000);
        if (!cfgRaw) return false;
        let parsed: unknown;
        try { parsed = JSON.parse(cfgRaw); } catch { return false; }
        const services = (parsed && typeof parsed === "object") ? (parsed as Record<string, unknown>).services : undefined;
        if (!services || typeof services !== "object") return false;
        // Only services whose container_name is already claimed by ANOTHER
        // dir (the clash set) need renaming.
        const NAME_RE = /^[A-Za-z0-9][A-Za-z0-9_.-]{0,120}$/;
        const renames: Array<{ svc: string; from: string; to: string }> = [];
        const taken = new Set<string>(claimedNames.keys());
        for (const [svc, defRaw] of Object.entries(services as Record<string, unknown>)) {
          const def = (defRaw && typeof defRaw === "object") ? (defRaw as Record<string, unknown>) : {};
          const cn = typeof def.container_name === "string" ? def.container_name.trim() : "";
          if (!cn) continue;
          const owner = claimedNames.get(cn);
          if (!owner || owner === dir) continue; // not a clash for this dir
          if (!NAME_RE.test(svc)) return false; // service name goes into YAML — validate
          // 3. new name <proj>-<originalName>; suffix -2/-3… until free.
          let cand = `${proj}-${cn}`;
          if (!NAME_RE.test(cand)) return false;
          if (taken.has(cand)) {
            let i = 2;
            while (i < 100 && taken.has(`${cand}-${i}`)) i++;
            cand = `${cand}-${i}`;
            if (!NAME_RE.test(cand)) return false;
          }
          taken.add(cand);
          renames.push({ svc, from: cn, to: cand });
        }
        if (!renames.length) return false; // config yielded nothing to rename
        // 3. Build + write the override compose file (same sftpWrite mechanism
        // the engine uses for every other generated file — no shell quoting).
        let yml = "services:\n";
        for (const rn of renames) yml += `  ${rn.svc}:\n    container_name: ${rn.to}\n`;
        const overrideDir = `${work}/clone-overrides`;
        const overridePath = `${overrideDir}/${proj}.yml`;
        await sh(conn, `mkdir -p ${overrideDir}`);
        await sftpWrite(sftp, overridePath, yml);
        // Build the base -f args from composeFiles (NOT ce.fileArg): once we
        // add `-f override`, compose stops auto-loading the default file, so
        // the base file(s) must be named explicitly. `-p ${proj}` namespaces
        // networks/volumes too, avoiding collisions with prod.
        const baseArgs = ce.composeFiles.map((cf) => `-f ${cf} `).join("");
        const cprefix = `${composeCmd} ${baseArgs}-f ${overridePath} ${ce.args}-p ${proj}`;
        await report(76, "Starting containers…", `  ${dir}: bringing up as clone with renamed container names (project ${proj}).`);
        // 4. Bring the clone up namespaced, with the same enospc-prune-retry.
        const run = () => sh(conn, `sh -c 'cd ${dir} && ${cprefix} up -d' >/dev/null 2>${work}/dumps/compose.err`, TRANSFER_TIMEOUT_MS);
        let cr = await run();
        let cerr = cleanLines((await sh(conn, `tail -c 400 ${work}/dumps/compose.err 2>/dev/null`)).stdout, 400);
        if (cr.code !== 0 && isEnospc(cerr)) {
          const reclaimed = await pruneDocker(conn);
          await report(76, "Starting containers…", `  ${dir} ran out of disk — freed ${human(reclaimed)} of build cache and retrying.`);
          cr = await run();
          cerr = cleanLines((await sh(conn, `tail -c 400 ${work}/dumps/compose.err 2>/dev/null`)).stdout, 400);
        }
        // 5. Health verdict — SAME state logic as the normal path, but the
        // `ps -q` targets THIS namespaced project (same -f … -f override -p).
        const stateHere = async (): Promise<{ running: number; bad: number }> => {
          const ids = cleanRows((await sh(conn, `sh -c 'cd ${dir} && ${cprefix} ps -q 2>/dev/null'`)).stdout, 4096)
            .filter((id) => /^[a-f0-9]{6,64}$/i.test(id));
          if (!ids.length) return { running: 0, bad: 0 };
          const raw = await sh(conn, `docker inspect -f '{{.State.Running}}|{{.State.Restarting}}|{{.State.Status}}|{{.State.ExitCode}}' ${ids.join(" ")} 2>/dev/null`);
          let running = 0, bad = 0;
          for (const line of cleanRows(raw.stdout, 8192)) {
            const [rr, rs, stt, ec] = line.split("|");
            if (rr === "true") { running++; continue; }
            if (rs === "true" || stt === "created" || (stt === "exited" && ec !== "0")) bad++;
          }
          return { running, bad };
        };
        let st = { running: 0, bad: 0 };
        for (const wait of [10, 12, 15, 18]) {
          await sh(conn, `sleep ${wait}`).catch(() => ({ code: 0, stdout: "", stderr: "" }));
          st = await stateHere();
          if (st.running > 0 && st.bad === 0) break;
        }
        const renList = renames.slice(0, 2).map((x) => `${x.from}→${x.to}`).join(", ") + (renames.length > 2 ? `, +${renames.length - 2} more` : "");
        if (st.running > 0 && st.bad === 0) {
          push({ step: `Compose up ${dir}`, status: "running", detail: `${st.running} service(s) running — brought up as a clone with renamed container names (${renList}) under project ${proj}; override at ${overridePath}` });
          await report(78, "Starting containers…", `  compose up in ${dir}: ${st.running} service(s) running (clone, renamed container names).`);
        } else if (st.running > 0) {
          push({ step: `Compose up ${dir}`, status: "failed", detail: `${st.bad} service(s) crash-looped or exited with an error (${st.running} running) — brought up as a clone with renamed container names (${renList}), override at ${overridePath} — check: cd ${dir} && ${cprefix} logs` });
          await report(78, "Starting containers…", `  compose up in ${dir}: ${st.bad} service(s) did not stay up (clone, renamed) — left for manual check.`);
        } else {
          const why = isEnospc(cerr)
            ? "the new server ran out of disk space while building/pulling its images"
            : lastErrorLine(cerr, 200) || "the containers started then exited (they didn't stay running)";
          push({ step: `Compose up ${dir}`, status: "failed", detail: `containers did not stay up${why ? `: ${why}` : ""} — brought up as a clone with renamed container names (${renList}), override at ${overridePath} — check: cd ${dir} && ${cprefix} logs` });
          await report(78, "Starting containers…", `  compose up in ${dir}: no service stayed running (clone, renamed) — left for manual start.`);
        }
        // Register the live names for THIS dir so a later clash is still caught:
        // the un-renamed originals plus the new renamed names.
        const collidedFrom = new Set(renames.map((x) => x.from));
        for (const n of names) if (!collidedFrom.has(n)) claimedNames.set(n, dir);
        for (const rn of renames) claimedNames.set(rn.to, dir);
        return true;
      })();
    } catch { renamed = false; }
  }
  if (!renamed) {
    push({
      step: `Compose up ${dir}`,
      status: "skipped",
      detail: `not started — its container_name "${clashName}" is already used by ${clashDir}. A container_name is absolute, so the same app's prod and staging can't both run on one host; run this one on a separate host, or give its services unique container_name values, then start it: cd ${dir} && ${composeCmd} ${ce.fileArg}${ce.args}up -d`,
    });
    await report(76, "Starting containers…", `  ${dir}: not started — container_name ${clashName} already used by ${clashDir}.`);
  }
  continue;
}

